import{_ as a,o as p,c as i,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"优化反应池垃圾桶","description":"","frontmatter":{"translationSource":{"title":"优化反应池垃圾桶","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=4td9eYzMz4ZLGmT0QcTpaQ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/optimizing-the-reactor-crucible-trash-can"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/optimizing-the-reactor-crucible-trash-can"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/optimizing-the-reactor-crucible-trash-can"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/optimizing-the-reactor-crucible-trash-can"}]]},"headers":[],"relativePath":"zh/optimizing-the-reactor-crucible-trash-can.md","filePath":"zh/page-4td9eYzMz4ZLGmT0QcTpaQ.md"}'),t={name:"zh/optimizing-the-reactor-crucible-trash-can.md"};function o(c,e,s,n,l,d){return p(),i("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="优化反应池垃圾桶" aria-hidden="true"></span><h1 id="优化反应池垃圾桶" tabindex="-1">优化反应池垃圾桶 <a class="header-anchor" href="#优化反应池垃圾桶" aria-label="Permalink to &quot;优化反应池垃圾桶&quot;">​</a></h1><blockquote><p>源页面 ID：<code>4td9eYzMz4ZLGmT0QcTpaQ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=4td9eYzMz4ZLGmT0QcTpaQ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>传统反应池垃圾桶基于多配方产物都堆满后反应池阻塞清空，需要经过超长时间才能销毁一轮。</p><p>优化目标是利用反应池虚空槽位，在反应结束前还未产生产物时把其原本要占据的槽位占住，使其无法落地，进而触发反应池阻塞清空</p><p>阻塞清空发生后，原本的产物会落地，为了处理这部分产物，需要定期把输出的产物流回来攒够50滴触发传统反应池垃圾桶的阻塞，或者干脆使用另一个反应池做垃圾桶。也可以考虑使用进行多个反应的扩容反应池来实现销毁</p><p>经过实验，目前暂时认为扩容反应池销毁符合以下规律：</p><p>0.疑似反应池只能在整数时刻接受物品输入及开始反应（液体不清楚，其它机器也可能存在此现象），若输入物品真实相位导致输入时刻非整数，反应池会卡住该物品 直至下一个整数时刻才会接受该输入物品</p><p>1.与其它机器一样，反应池会先消耗原料，经过对应配方耗时后，若存在足够数量的可用输出槽则输出产物并完成该次配方生产；若不存在则判定为该配方阻塞，直到有足够数量的可用输出槽。与其它机器不同，反应池的所有槽都可以是输出槽</p><p>2.在反应池内无任何物品累积时，不同配方的不同原料可以共用一个输入槽，不同配方的产物可以共用一个输出槽</p><p>3.当扩容反应池存在两个及以上配方阻塞时，可以触发销毁，清空此时池内所有物品。注意，触发销毁仅需满足配方阻塞，无论此时池内是否存在该配方的原料</p><p>4.触发销毁后，被阻塞的配方产物不会被销毁而是立刻进入反应池</p><p>5.对于同一刻输入的物品和完成配方的产物，外界输入总是先于配方产物进行占槽</p><p>根据这些规律可以得到以下销毁方案：</p><p><span id="source-block-gV6UDHqnrjQq9XSlUMomE3"></span></p><span class="logistics-source-anchor" id="无浪费销毁-用于1-5最大净产" aria-hidden="true"></span><h2 id="无浪费销毁-用于1-5最大净产" tabindex="-1">无浪费销毁（用于1.5最大净产） <a class="header-anchor" href="#无浪费销毁-用于1-5最大净产" aria-label="Permalink to &quot;无浪费销毁（用于1.5最大净产）&quot;">​</a></h2><p>为保证无浪费，触发销毁时反应池内不能存在任何有价值原料。此处以壤晶扩反为例，该扩容反应池存在三个配方：</p><p>1息壤+1清水==1液化息壤（2s）</p><p>1液化息壤+1污水==1壤晶废液+1惰性壤晶废液（2s）</p><p>2壤晶废液+1蓝铁粉末==1壤晶+1污水（2s）</p><p>其中，反应1和反应2需要一直进行。根据规律5，若持续连续输入息壤，在触发销毁时输入的息壤会挤占液化息壤的输出槽，因此此时输入的息壤会被销毁而无法进入配方生产。所以要想避免浪费息壤，必须在销毁时停止输入息壤</p><p>除需要被销毁的污水外，还有7个槽，可将需要的7种杂物可分为占槽杂物和触发杂物。占槽杂物指提前输入反应池的杂物，需要确保不会提前触发销毁。触发杂物指在触发销毁前的瞬间输入的杂物。稍过量的清水也可以作为一种占槽杂物。触发杂物的上限取决于扩反的输入口数量，为了方便对齐相位仅使用固体；而下限取决于最多能有几种占槽杂物。实验表明，对于该系统，存在占槽4种杂物时便有机会触发销毁，但占槽杂物越少越安全，故此处选取3种占槽杂物，4种触发杂物的方案</p><p>由于选择了4种触发杂物，这意味着必须在息壤输入带上周期插入一个杂物，此时输入息壤的速率为30*(T-2)/T u/min。净产对于该扩容反应池生产的下限为13.75 u/min壤晶，输入的息壤不得少于27.5 u/min，故T≥24。净产需要销毁的污水量为115.35 u/min（不含参与反应的污水），反应池的污水容量为50，故T≤20000/769。又因为需要确保一个周期内的壤晶废液被完全反应，一个周期内输入的息壤数量（T/2-1）必须是偶数，所以仅有T=26s符合需求。</p><p>因此，息壤输入带为：每12息壤1杂物的混带，周期13（物品）。由于无空位汇流器全阻塞打混无法构造周期为13的混带，此处采用将均匀的1/13限速杂物插入息壤输入带来实现混带。4种触发杂物需要同时进入扩容反应池，因此另构造三个1/13限速杂物，其一插入蓝铁输入带，另外两个对齐相位后直接进入反应池；3种占槽杂物则从清水入口、蓝铁输入带空位进入反应池。</p><p><span id="source-block-y4lFMmpZPZZbTjFmgvLqlo"></span></p><span class="logistics-source-anchor" id="高效销毁-用于芽针-荞花放生机" aria-hidden="true"></span><span class="logistics-source-anchor" id="efficient-disposal-for-△" aria-hidden="true"></span><span class="logistics-source-anchor" id="高效销毁-用于△" aria-hidden="true"></span><h2 id="高效销毁-用于芽针-荞花放生机" tabindex="-1">高效销毁（用于<a href="/endfield-skydoc/zh/yazhen-buckflower-release-machine">芽针/荞花放生机</a>） <a class="header-anchor" href="#高效销毁-用于芽针-荞花放生机" aria-label="Permalink to &quot;高效销毁（用于[芽针/荞花放生机](page-CJl0m5vqcG6gAnt645AywF.md)）&quot;">​</a></h2><p>传统放生机通过同时生产芽针溶液和锦草溶液，形成双配方堵塞而触发销毁。单扩反除接受芽针、锦草粉末外，还能再接受一条芽针和芽针种子输入，每个扩反可供150pm芽针生产计数（实际略小于150）。</p><p>相较于传统销毁，高效销毁主要区别在不需要一直反应，至少只需要触发销毁时发生一次反应。然而为了触发高效销毁，必须占满8个槽。用于阻塞的配方仍选择水+两种粉末=两种溶液（其他反应基本上支持不起高消耗）。触发销毁时，两种溶液都要无法输出，因此我们可以只在触发反应时给一点水，这样还能连带着把堆积的粉末消耗掉。</p><p>故槽位为1个计数植物槽，4个杂物占位槽，2个粉末槽，1个水槽。5个杂物只需在触发销毁时有1个即可，粉末则需要至少有2个，水则需要在触发销毁时至少通入3个，其他时候不能通入。</p><p>杂物的可选项：源石、蓝铁、蓝铁粉、酸、污水（需要和酸混管）。注意水要单独一个入口输入，防止其他杂物液体堵住水</p><p>因此，为了尽可能高效刷计数，应把120pm的固体输入流量划分为杂物流量和计数植物流量。我们假设每2n秒销毁一次，则这2n秒中需要输入四种杂物各1，两种粉末各2。如果按三种固体杂物和一种流体杂物计，则剩余可输入4n-7个计数植物。显然，要满足4n-7&lt;50，可得n&lt;14.25。</p><p>植物的销毁效率为：(4n-7)/2n=2-7/2n（每秒）=120-210/n（每分钟）。因此极限效率为105.26每分钟，对应约210的芽针计数。此时每种杂物需求为每分钟120/57个</p><p>作为占地对比，传统销毁机单核150pm芽针计数，需要3组采种种植+1扩反1粉碎1采种。高效销毁单核210pm芽针计数，如果忽略杂物和另一粉末的生产，则需3.5组采种种植+1扩反1粉碎。相当于占地不变的情况下提效了40%。然而，它的问题是需要构造一条15芽针+6.几杂物+8.几粉末的混带。这可能会带来很多取货口占地的消耗。此外，还需要将两种产物溶液一并导入传统垃圾桶中。</p><p>初代雷霆机：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-dae8faf1748ee778.q90-711cf24473c28cc2.webp" alt="优化反应池垃圾桶"></p><p>MAN，what can I say？</p><p>水和芽针的大肠是为了启动时慢点进入，这个问题不算大；但是主要的难点一是需要30秒连进3个水，要么换成粉末同时进入触发销毁，二是构造混带，图中还是直接用4/m和2/m的版本简化了，事实上我找了半天没法简单用2汇3汇做出a&gt;4,b&gt;4,c&gt;2,d&gt;2,e&gt;2（比如三汇，ab各拿1份，cde再三汇1份，结果是5，5，1.67，1.67，1.67；再比如15分18份，ab各拿5份，剩下8合起来再分3份给cde才行）。这个简单版本销毁90pm芽针（实际应该能达到106，但最后一条带混芽针最后还是堵了，模拟器问题可能）。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c521d01aeadc6406.q90-87c97d45f829ffb9.webp" alt="优化反应池垃圾桶"></p><div class="logistics-image-caption" data-source-block="bGgaHdvZHpYiBaeoGwuvMW"><p>销毁机MKII</p></div><p><a href="https://www.bilibili.com/video/BV1w9pv6YEop" target="_blank" rel="noreferrer">【终末地/基建】高速销毁机（30s销毁一次，同物品销毁速度可达100/m）</a></p><blockquote><p>最初这个技术是用于1.4最大净产中销毁污水来省电的，研发者包括君老大@樊二のいすぼくろ赛高 和言老大等，不过那边实现更麻烦，似乎后来也一直忙的没空整，还是我这赤石芽针放生科技琢磨了一下做了一台高速销毁版的机子出来（</p></blockquote><p>[芽针放生机MK.II]分享码EF01o5u1U7OA061UIieO<br> 注意，水暗管连接前要先往里倒1滴污水，让污水在里面先循环跑起来<br> 暗管直接各连一个水泵酸泵就行，当然实际上也用不了这么多。3个杂物可以换别的，酸也能换别的液体，总之需要占4个位置，注意不要选息壤这种跟水反应的</p><p>实际理论极限应该能达到每分钟销毁106，剩余14里面粉末拿4+4，三种杂物拿2+2+2，但是这个分流结构不太好做。视频里100的简单很多。</p><p>结合了orirock提供的整流器，30秒连续输出3水<a href="/endfield-skydoc/zh/flow-regularizer">整流器</a></p><p>[芽针放生机MK.II]分享码EF01o5u1U7OA061UIieO</p><p>使用方法：<strong>放下后先往水暗管里加1滴污水，然后再连水泵和酸泵</strong>。第四个口子的准入口建议稳定后再开。输出的两个溶液需要处理掉。三个杂物可以换别的。记得别的地方要产两种粉末。</p><p>以下是乾震佬改进的版本，能够基于酸的堵塞来触发3个水的输出从而触发销毁，生产的2个药液灌装后又能触发2个药粉和杂物输入，相当于自动调速了。两种架构体现出了时序控制和阻塞控制的区别。</p><p>智能高速销毁机：EF01u28I5E12805a1AoOU</p><p><a href="https://www.bilibili.com/video/BV1VTp36mESS" target="_blank" rel="noreferrer">【赤石基教】智能高速销毁机</a></p><blockquote><p>唉，其实不想发的，传出去让人说“还是太有用了”……但不发良心不安，还是简单剪辑一下发出来了，大家偷偷用别扩散哈，或者改得面目全非再用</p></blockquote><p>参考了@蓝海露花_kokobird 的BV1w9pv6YEop，而他的是用于1.4最大净产中销毁污水来省电的，研发有@樊二のいすぼくろ赛高 和言等人参与，他们设计的装置太有用了，导致我把这装置改得更赤石了也还是显得很有用，但绝不是因为我的改造有用！</p><p>智能高速销毁机：EF01u28I5E12805a1AoOU</p><p>老大又又更新了。。</p><p><a href="https://www.bilibili.com/video/BV1WBp76SEUi" target="_blank" rel="noreferrer">【赤石基教】超速废水处理厂</a></p><blockquote><p>上一期的BV1VTp36mESS，昨晚有人想让我试试理论上限，因此简单改造后测试了一下。受制于清水输入速度，污水销毁速度上限大概是190左右，所以就直接设计成稳定的180销毁上限了~</p></blockquote><p>参考了@蓝海露花_kokobird 的BV1w9pv6YEop，而他的是用于1.4最大净产中销毁污水来省电的，研发有君@樊二のいすぼくろ赛高 和言等人参与。他们设计的装置太有用了，以至于我把这装置改得如此赤石也还是看起来像模像样的，绝不是因为我的改造有用！</p><p>超速废水处理厂：EF0193a6I8A3aeO6i5uI2</p><p><span id="source-block-djI0fsbTZuU6JJ46fwu8c1"></span></p><span class="logistics-source-anchor" id="高效壤晶污水处理" aria-hidden="true"></span><h2 id="高效壤晶污水处理" tabindex="-1">高效壤晶污水处理 <a class="header-anchor" href="#高效壤晶污水处理" aria-label="Permalink to &quot;高效壤晶污水处理&quot;">​</a></h2><p>由于规律4的存在，可能可以在壤晶反应池中进行污水销毁，并且不浪费反应产物，研究相关理论是否成立与所需的输入规律。</p></div>',1)])])}const b=a(t,[["render",o]]);export{u as __pageData,b as default};
